package com.nigson.integration.carrier;
import java.util.*;
import java.time.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.integration.providers.PandagoAdapter;
import com.nigson.integration.platform.AuditWriter;
import com.nigson.shared.security.*;
import com.nigson.shared.events.EventCodec;
import tools.jackson.databind.JsonNode;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
class PandagoCancellationPersistenceTest {
 PandagoBookingPersistenceTest f;PandagoCancellationService service;UUID id;JsonNode body;PrivateWorkload.Proof proof;
 @BeforeEach void setup(){f=new PandagoBookingPersistenceTest();f.setup();id=UUID.randomUUID();service=new PandagoCancellationService(f.jdbc,new DataSourceTransactionManager(f.jdbc.getDataSource()),f.provider,f.clock,f.generation,f.source.minusSeconds(5),f.source.plusSeconds(600),new AuditWriter(f.jdbc,f.clock,new io.micrometer.core.instrument.simple.SimpleMeterRegistry()));body=EventCodec.JSON.valueToTree(Map.of("cancellationId",id,"shipmentId",f.shipment,"bookingRequestId",f.reference,"reference",f.reference.toString(),"mode","MOCK","requestedAt",f.source));proof=new PrivateWorkload.Proof("nigson-commerce","synthetic-commerce",PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-198")).findFirst().orElseThrow(),null);}
 @AfterEach void close(){if(f!=null&&f.jdbc!=null){f.jdbc.update("DELETE FROM integration.carrier_cancellation WHERE shipment_id=?",f.shipment);f.close();}}
 JsonNode request(){return service.request(proof,body,id.toString(),UUID.randomUUID());}
 void booked(){f.worker.poll();when(f.provider.cancel("stage-order","REASON_UNKNOWN")).thenAnswer(c->{assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return PandagoAdapter.Cancellation.CANCELLED;});}
 @Test void unpreparedBookingIsSuppressedWithoutAnyProviderWrite(){request();service.process(id);assertThat(request().path("state").asString()).isEqualTo("CANCELLED");f.due();f.worker.poll();verify(f.provider,never()).confirm(any(),any(),any(),any(),any(),any(),any(),any());verify(f.provider,never()).cancel(any(),any());}
 @Test void bookedDeliveryCancelsOnceAndReplaysExactReceipt(){booked();request();service.process(id);var first=request();assertThat(first.path("state").asString()).isEqualTo("CANCELLED");assertThat(first.path("receipt").path("reference").asString()).isEqualTo(f.reference.toString());service.process(id);assertThat(request()).isEqualTo(first);verify(f.provider,times(1)).cancel("stage-order","REASON_UNKNOWN");}
 @Test void timeoutIsUnknownAndReadOnlyReconciliationProvesCancellation(){booked();when(f.provider.cancel(any(),any())).thenThrow(new ProviderHttp.Failure("RESPONSE_LOST",true,503));when(f.provider.order("stage-order")).thenReturn(new PandagoAdapter.Order("stage-order",f.reference.toString(),"NEW"));request();service.process(id);var unknown=request();assertThat(unknown.path("state").asString()).isEqualTo("UNKNOWN");service.process(id);assertThat(request()).isEqualTo(unknown);when(f.provider.order("stage-order")).thenReturn(new PandagoAdapter.Order("stage-order",f.reference.toString(),"CANCELLED"));service.process(id);assertThat(request().path("state").asString()).isEqualTo("CANCELLED");verify(f.provider,times(1)).cancel(any(),any());}
 @Test void authoritativeConflictRejectsButMissingOrderDoesNotProveCancellation(){booked();when(f.provider.cancel(any(),any())).thenThrow(new ProviderHttp.Failure("PROVIDER_HTTP_409",false,409));request();service.process(id);assertThat(request().path("state").asString()).isEqualTo("REJECTED");}
 @Test void preparedWithoutProviderIdNeverCancelsOrCreatesAgain(){f.jdbc.update("UPDATE integration.carrier_booking SET prepared_at=now(),account_hash=?,state='UNKNOWN',next_poll_at=NULL WHERE shipment_id=?","1".repeat(64),f.shipment);request();service.process(id);service.process(id);assertThat(request().path("state").asString()).isEqualTo("UNKNOWN");verify(f.provider,never()).cancel(any(),any());verify(f.provider,never()).confirm(any(),any(),any(),any(),any(),any(),any(),any());}
 @Test void restoreGenerationAndSubmittedCheckpointNeverGrantAnotherDelete(){booked();request();f.jdbc.update("UPDATE integration.carrier_cancellation SET generation=? WHERE id=?",UUID.randomUUID(),id);when(f.provider.order("stage-order")).thenReturn(new PandagoAdapter.Order("stage-order",f.reference.toString(),"NEW"));service.process(id);assertThat(request().path("state").asString()).isEqualTo("UNKNOWN");verify(f.provider,never()).cancel(any(),any());}
 @Test void cancellationDuringQuoteWinsBeforeBookingPreparation(){when(f.commerce.context(f.shipment)).thenAnswer(c->{request();service.process(id);return f.context("PAID",null);});f.worker.poll();assertThat(request().path("state").asString()).isEqualTo("CANCELLED");verify(f.provider,never()).confirm(any(),any(),any(),any(),any(),any(),any(),any());}
 @Test void changedRequestAndWrongWorkloadAreDenied(){request();var altered=body.deepCopy();((tools.jackson.databind.node.ObjectNode)altered).put("reference","other-order");assertThatThrownBy(()->service.request(proof,altered,id.toString(),UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");assertThatThrownBy(()->service.request(new PrivateWorkload.Proof("nigson-experience","bad",proof.route(),null),body,id.toString(),UUID.randomUUID())).hasMessage("ACCESS_DENIED");verify(f.provider,never()).cancel(any(),any());}
 @Test void bookingOutcomeCanBecomeKnownBeforeTheFirstCancellationWrite(){f.jdbc.update("UPDATE integration.carrier_booking SET prepared_at=now(),account_hash=?,state='UNKNOWN',next_poll_at=NULL WHERE shipment_id=?","1".repeat(64),f.shipment);request();service.process(id);assertThat(request().path("state").asString()).isEqualTo("UNKNOWN");f.jdbc.update("UPDATE integration.carrier_booking SET provider_shipment_id='stage-order',state='BOOKED' WHERE shipment_id=?",f.shipment);when(f.provider.cancel("stage-order","REASON_UNKNOWN")).thenReturn(PandagoAdapter.Cancellation.CANCELLED);service.process(id);assertThat(request().path("state").asString()).isEqualTo("CANCELLED");verify(f.provider,times(1)).cancel(any(),any());}
 @Test void legacyAcknowledgementAndMissingOrderRemainUnknownUntilReadProof(){booked();when(f.provider.cancel(any(),any())).thenReturn(PandagoAdapter.Cancellation.LEGACY_ACKNOWLEDGED);when(f.provider.order("stage-order")).thenThrow(new ProviderHttp.Failure("PROVIDER_HTTP_404",false,404));request();service.process(id);assertThat(request().path("state").asString()).isEqualTo("UNKNOWN");service.process(id);verify(f.provider,times(1)).cancel(any(),any());}

 @Test void conflictFromOrderReadAfterLegacyAcknowledgementIsNotCancellationRefusal(){booked();when(f.provider.cancel(any(),any())).thenReturn(PandagoAdapter.Cancellation.LEGACY_ACKNOWLEDGED);when(f.provider.order("stage-order")).thenThrow(new ProviderHttp.Failure("PROVIDER_HTTP_409",false,409));request();service.process(id);assertThat(request().path("state").asString()).isEqualTo("UNKNOWN");}

}
